process.env.JWT_SECRET = 'testsecret';
const { sequelize } = require('./src/models');
const { register, login } = require('./src/controllers/authController');
const { protect, restrictTo } = require('./src/middleware/auth');

// minimal res mock
function mockRes() {
  return { code: null, body: null,
    status(c){ this.code=c; return this; },
    json(b){ this.body=b; return this; } };
}
function run(mw, req) { return new Promise(r => { const res=mockRes(); const next=()=>{res.nextCalled=true; r(res);}; Promise.resolve(mw(req,res,next)).then(()=>r(res)); }); }

(async () => {
  await sequelize.sync({ force: true });

  // register
  let res = await run(register, { body: { name:'Klemens', email:'k@x.com', password:'secret1' } });
  console.log('register:', res.code, JSON.stringify(res.body), 'no hash:', !('password_hash' in res.body));

  // duplicate email
  res = await run(register, { body: { name:'Klemens', email:'k@x.com', password:'secret1' } });
  console.log('dup email:', res.code, JSON.stringify(res.body));

  // bad validation
  res = await run(register, { body: { name:'K', email:'bad', password:'12' } });
  console.log('validation:', res.code);

  // login good
  res = await run(login, { body: { email:'k@x.com', password:'secret1' } });
  const token = res.body.token;
  console.log('login ok:', res.code, 'has token:', !!token);

  // login wrong pw
  res = await run(login, { body: { email:'k@x.com', password:'wrong' } });
  console.log('login bad pw:', res.code, JSON.stringify(res.body));

  // login unknown email (same generic 401)
  res = await run(login, { body: { email:'none@x.com', password:'whatever' } });
  console.log('login unknown:', res.code, JSON.stringify(res.body));

  // protect: valid token
  let req = { headers: { authorization: 'Bearer ' + token } };
  res = await run(protect, req);
  console.log('protect valid:', res.nextCalled === true, 'req.user.role:', req.user && req.user.role);

  // protect: no token
  res = await run(protect, { headers: {} });
  console.log('protect no token:', res.code);

  // protect: bad token
  res = await run(protect, { headers: { authorization: 'Bearer garbage' } });
  console.log('protect bad token:', res.code);

  // restrictTo: allowed
  res = await run(restrictTo('resident','admin'), { user: { role:'resident' } });
  console.log('restrict allow:', res.nextCalled === true);

  // restrictTo: forbidden
  res = await run(restrictTo('admin'), { user: { role:'resident' } });
  console.log('restrict forbid:', res.code);

  await sequelize.close();
})().catch(e => { console.error('FAIL:', e); process.exit(1); });
"

