node -e "
process.env.DATABASE_URL = 'sqlite::memory:';
const { sequelize, User, ResidentReport, CaseStatusLog } = require('./src/models');
(async () => {
  await sequelize.sync({ force: true });

  const user = await User.create({ name: 'Resident A', email: 'a@x.com', password_hash: 'h' });
  const staff = await User.create({ name: 'Staff B', email: 'b@x.com', password_hash: 'h', role: 'staff' });

  const report = await ResidentReport.create({
    category: 'community_cat',
    title: 'Injured cat at void deck',
    description: 'Cat limping near lift lobby',
    photo_urls: ['https://res.cloudinary.com/demo/cat.jpg'],
    gps_lat: 1.3521, gps_lng: 103.8198,
    block_number: '123A', floor_level: '01',
    reported_by: user.id,
  });
  console.log('report:', report.id, report.status, report.is_deleted, JSON.stringify(report.photo_urls));

  const log = await CaseStatusLog.create({
    report_id: report.id, old_status: 'open', new_status: 'in_progress', changed_by: staff.id,
  });
  console.log('status log:', log.id, log.old_status, '->', log.new_status, 'at', !!log.createdAt);

  // associations
  const full = await ResidentReport.findByPk(report.id, {
    include: [{ association: 'reporter' }, { model: CaseStatusLog, include: [{ association: 'changer' }] }],
  });
  console.log('reporter:', full.reporter.name);
  console.log('logs:', full.CaseStatusLogs.length, 'changer:', full.CaseStatusLogs[0].changer.name);

  // defaults: minimal report
  const min = await ResidentReport.create({ category: 'other', title: 't', description: 'd', reported_by: user.id });
  console.log('defaults:', min.status, min.is_deleted, JSON.stringify(min.photo_urls), min.gps_lat);

  // enum rejection
  try { await ResidentReport.create({ category: 'nope', title: 't', description: 'd', reported_by: user.id }); console.log('ERROR: bad category accepted'); }
  catch (e) { console.log('bad category rejected:', e.name); }

  await sequelize.close();
  console.log('SMOKE TEST OK');
})().catch(e => { console.error('FAIL:', e.message); process.exit(1); });
"

