process.env.DATABASE_URL = 'sqlite::memory:';
process.env.JWT_SECRET = 'smoke-secret';

const request = require('supertest');
const app = require('./src/index');
const { sequelize } = require('./src/models');

function check(label, cond, extra) {
  console.log((cond ? 'PASS' : 'FAIL') + ' - ' + label + (extra ? ' | ' + extra : ''));
  if (!cond) process.exitCode = 1;
}

(async () => {
  await sequelize.sync({ force: true });

  // setup: register + login 4 users
  const users = {};
  for (const [key, role] of [['res1', 'resident'], ['res2', 'resident'], ['staff', 'staff'], ['admin', 'admin']]) {
    await request(app).post('/api/auth/register')
      .send({ name: key, email: key + '@x.com', password: 'secret1', role });
    const login = await request(app).post('/api/auth/login')
      .send({ email: key + '@x.com', password: 'secret1' });
    users[key] = 'Bearer ' + login.body.token;
  }

  // 1. resident creates a report
  let r = await request(app).post('/api/reports').set('Authorization', users.res1)
    .send({ category: 'pigeon', title: 'Pigeons nesting', description: 'Corridor ledge', gps_lat: 1.35, gps_lng: 103.82, block_number: '123A' });
  check('create -> 201', r.status === 201, 'id=' + r.body.id);
  check('reported_by from token, not body', r.body.reported_by === 1);
  const reportId = r.body.id;

  // body cannot spoof reported_by
  r = await request(app).post('/api/reports').set('Authorization', users.res2)
    .send({ category: 'pest', title: 'Ants', description: 'Void deck', reported_by: 999 });
  check('reported_by in body ignored', r.status === 201 && r.body.reported_by === 2);
  const report2Id = r.body.id;

  // 2. validation + auth failures
  r = await request(app).post('/api/reports').set('Authorization', users.res1)
    .send({ category: 'bogus', title: 'x', description: 'y' });
  check('bad category -> 400', r.status === 400);
  r = await request(app).post('/api/reports')
    .send({ category: 'pest', title: 'x', description: 'y' });
  check('no token -> 401', r.status === 401);
  r = await request(app).post('/api/reports').set('Authorization', users.res1)
    .send({ category: 'pest', title: 'x'.repeat(201), description: 'y' });
  check('title > 200 -> 400', r.status === 400);

  // 3. list scoping
  r = await request(app).get('/api/reports').set('Authorization', users.res1);
  check('resident sees only own', r.status === 200 && r.body.length === 1 && r.body[0].reported_by === 1);
  check('list includes reporter name', r.body[0].reporter && r.body[0].reporter.name === 'res1');
  r = await request(app).get('/api/reports').set('Authorization', users.staff);
  check('staff sees all', r.status === 200 && r.body.length === 2);

  // 4. get one - access control
  r = await request(app).get('/api/reports/' + reportId).set('Authorization', users.res2);
  check('resident viewing others -> 403', r.status === 403);
  r = await request(app).get('/api/reports/' + reportId).set('Authorization', users.res1);
  check('owner can view own', r.status === 200);
  r = await request(app).get('/api/reports/9999').set('Authorization', users.staff);
  check('missing id -> 404', r.status === 404);

  // 5. status update
  r = await request(app).patch('/api/reports/' + reportId + '/status').set('Authorization', users.res1)
    .send({ status: 'in_progress' });
  check('resident patch status -> 403', r.status === 403);
  r = await request(app).patch('/api/reports/' + reportId + '/status').set('Authorization', users.staff)
    .send({ status: 'in_progress' });
  check('staff patch -> 200 + new status', r.status === 200 && r.body.status === 'in_progress');
  r = await request(app).patch('/api/reports/' + reportId + '/status').set('Authorization', users.staff)
    .send({ status: 'in_progress' });
  check('same status -> 200, no error', r.status === 200);
  r = await request(app).patch('/api/reports/' + reportId + '/status').set('Authorization', users.staff)
    .send({ status: 'closed' });
  check('invalid status -> 400', r.status === 400);

  // 6. status history visible with changer name; no-change patch logged nothing
  r = await request(app).get('/api/reports/' + reportId).set('Authorization', users.res1);
  const logs = r.body.CaseStatusLogs || [];
  check('exactly 1 log after duplicate patch', logs.length === 1, 'logs=' + logs.length);
  check('log old->new + changer name', logs[0] && logs[0].old_status === 'open' && logs[0].new_status === 'in_progress' && logs[0].changer.name === 'staff');

  // 7. soft delete
  r = await request(app).delete('/api/reports/' + report2Id).set('Authorization', users.staff);
  check('staff delete -> 403', r.status === 403);
  r = await request(app).delete('/api/reports/' + report2Id).set('Authorization', users.admin);
  check('admin delete -> 200', r.status === 200);
  r = await request(app).delete('/api/reports/' + report2Id).set('Authorization', users.admin);
  check('double delete -> 404', r.status === 404);
  r = await request(app).get('/api/reports/' + report2Id).set('Authorization', users.admin);
  check('deleted report get -> 404', r.status === 404);
  r = await request(app).get('/api/reports').set('Authorization', users.staff);
  check('deleted excluded from list', r.body.length === 1);
  const { ResidentReport } = require('./src/models');
  const row = await ResidentReport.findByPk(report2Id);
  check('row still in DB (soft delete)', row !== null && row.is_deleted === true);

  // 8. query filters
  r = await request(app).get('/api/reports?status=in_progress').set('Authorization', users.staff);
  check('filter by status', r.body.length === 1 && r.body[0].status === 'in_progress');
  r = await request(app).get('/api/reports?category=flora_health').set('Authorization', users.staff);
  check('filter by category (none match)', r.body.length === 0);

  await sequelize.close();
  console.log(process.exitCode ? 'SMOKE TEST FAILED' : 'SMOKE TEST OK');
})().catch((e) => { console.error('FATAL:', e); process.exit(1); });

