  r = await request(app).get('/api/reports/' + reportId).set('Authorization', users.res1);
  check('owner can view own', r.status === 200);
  r = await request(app).get('/api/reports/9999').set('Authorization', users.staff);
  check('missing id -> 404', r.status === 404);

  // 5. status update
  r = await request(app).patch('/api/reports/' + reportId + '/status').set('Authorization', users.res1)
    .send({ status: 'in_progress' });
  check('resident patch status -> 403', r.status === 403);
  r = await request(app).patch('/api/reports/' + reportId + '/status').set('Authorization', users.staff)
    .send({ status: 'in_progress' });
  check('staff patch -> 200 + new status', r.status === 200 && r.body.status === 'in_progress');
  r = await request(app).patch('/api/reports/' + reportId + '/status').set('Authorization', users.staff)
    .send({ status: 'in_progress' });
  check('same status -> 200, no error', r.status === 200);
  r = await request(app).patch('/api/reports/' + reportId + '/status').set('Authorization', users.staff)
    .send({ status: 'closed' });
  check('invalid status -> 400', r.status === 400);

  // 6. status history visible with changer name; no-change patch logged nothing
  r = await request(app).get('/api/reports/' + reportId).set('Authorization', users.res1);
  const logs = r.body.CaseStatusLogs || [];
  check('exactly 1 log after duplicate patch', logs.length === 1, 'logs=' + logs.length);
  check('log old->new + changer name', logs[0] && logs[0].old_status === 'open' && logs[0].new_status === 'in_progress' && logs[0].changer.name === 'staff');

  // 7. soft delete
  r = await request(app).delete('/api/reports/' + report2Id).set('Authorization', users.staff);
  check('staff delete -> 403', r.status === 403);
  r = await request(app).delete('/api/reports/' + report2Id).set('Authorization', users.admin);
  check('admin delete -> 200', r.status === 200);
  r = await request(app).delete('/api/reports/' + report2Id).set('Authorization', users.admin);
  check('double delete -> 404', r.status === 404);
  r = await request(app).get('/api/reports/' + report2Id).set('Authorization', users.admin);
  check('deleted report get -> 404', r.status === 404);
  r = await request(app).get('/api/reports').set('Authorization', users.staff);
  check('deleted excluded from list', r.body.length === 1);
  const { ResidentReport } = require('./src/models');
  const row = await ResidentReport.findByPk(report2Id);
  check('row still in DB (soft delete)', row !== null && row.is_deleted === true);

  // 8. query filters
  r = await request(app).get('/api/reports?status=in_progress').set('Authorization', users.staff);
  check('filter by status', r.body.length === 1 && r.body[0].status === 'in_progress');
  r = await request(app).get('/api/reports?category=flora_health').set('Authorization', users.staff);
  check('filter by category (none match)', r.body.length === 0);

  await sequelize.close();
  console.log(process.exitCode ? 'SMOKE TEST FAILED' : 'SMOKE TEST OK');
})().catch((e) => { console.error('FATAL:', e); process.exit(1); });

